    quarter_num SMALLINT,
    year_quarter CHAR(7),
    year SMALLINT,
    CONSTRAINT pk_dim_date PRIMARY KEY (date_key),
    CONSTRAINT uq_dim_date_full_date UNIQUE (full_date),
    CONSTRAINT ck_dim_date_1 CHECK (date_key = -1 OR full_date IS NOT NULL),
    CONSTRAINT ck_dim_date_2 CHECK (month_num BETWEEN 1 AND 12),
    CONSTRAINT ck_dim_date_3 CHECK (quarter_num BETWEEN 1 AND 4),
    CONSTRAINT ck_dim_date_4 CHECK (day_of_week_num BETWEEN 1 AND 7)
);
