-- Transaction fact. Grain: One row per product line within a customer order (order_id + order_item_id). Each row is one unit of one product sold by one seller.
CREATE TABLE project_dw.fact_order_items (
    order_id VARCHAR(32) NOT NULL,
    order_item_id SMALLINT NOT NULL,
