    item_quantity SMALLINT NOT NULL,
    CONSTRAINT pk_fact_order_items PRIMARY KEY (order_id, order_item_id),
    CONSTRAINT fk_fact_order_items_order_purchase_date_key FOREIGN KEY (order_purchase_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_order_items_shipping_limit_date_key FOREIGN KEY (shipping_limit_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_order_items_customer_key FOREIGN KEY (customer_key) REFERENCES project_dw.dim_customer (customer_key),
    CONSTRAINT fk_fact_order_items_product_key FOREIGN KEY (product_key) REFERENCES project_dw.dim_product (product_key),
    CONSTRAINT fk_fact_order_items_seller_key FOREIGN KEY (seller_key) REFERENCES project_dw.dim_seller (seller_key),
    CONSTRAINT fk_fact_order_items_order_status_key FOREIGN KEY (order_status_key) REFERENCES project_dw.dim_order_status (order_status_key),
    CONSTRAINT ck_fact_order_items_1 CHECK (item_price > 0),
    CONSTRAINT ck_fact_order_items_2 CHECK (freight_value >= 0),
    CONSTRAINT ck_fact_order_items_3 CHECK (item_quantity >= 1),
    CONSTRAINT ck_fact_order_items_4 CHECK (item_gross_value = item_price + freight_value)
);
COMMENT ON TABLE project_dw.fact_order_items IS 'Transaction fact. Grain: One row per product line within a customer order (order_id + order_item_id). Each row is one unit of one product sold by one seller.';
COMMENT ON COLUMN project_dw.fact_order_items.order_id IS 'Order identifier (degenerate dimension). Part of PK.';
COMMENT ON COLUMN project_dw.fact_order_items.order_item_id IS 'Line sequence within the order (1..21). Part of PK.';
COMMENT ON COLUMN project_dw.fact_order_items.order_purchase_date_key IS 'Date the order was placed.';
COMMENT ON COLUMN project_dw.fact_order_items.shipping_limit_date_key IS 'Seller''s deadline to hand the item to the carrier.';
COMMENT ON COLUMN project_dw.fact_order_items.customer_key IS 'Customer who placed the order.';
COMMENT ON COLUMN project_dw.fact_order_items.product_key IS 'Product sold.';
COMMENT ON COLUMN project_dw.fact_order_items.seller_key IS 'Seller who sold the item.';
COMMENT ON COLUMN project_dw.fact_order_items.order_status_key IS 'Current status of the parent order (used to exclude cancelled sales).';
COMMENT ON COLUMN project_dw.fact_order_items.item_price IS 'Selling price of the item (BRL), excluding freight.';
COMMENT ON COLUMN project_dw.fact_order_items.freight_value IS 'Freight charged for this item (BRL).';
COMMENT ON COLUMN project_dw.fact_order_items.item_gross_value IS 'item_price + freight_value.';
COMMENT ON COLUMN project_dw.fact_order_items.item_quantity IS 'Units on this row (always 1 in source; repeated rows mean quantity > 1).';

-- Accumulating snapshot fact. Grain: One row per customer order (order_id), updated as the order passes purchase, approval, carrier hand-off and delivery milestones.
CREATE TABLE project_dw.fact_orders (
    order_id VARCHAR(32) NOT NULL,
    customer_key INTEGER NOT NULL,
    order_status_key SMALLINT NOT NULL,
    order_purchase_date_key INTEGER NOT NULL,
    approved_date_key INTEGER NOT NULL,
    carrier_date_key INTEGER NOT NULL,
    delivered_date_key INTEGER NOT NULL,
    estimated_delivery_date_key INTEGER NOT NULL,
    purchase_hour SMALLINT NOT NULL,
    item_count SMALLINT NOT NULL,
    order_item_value NUMERIC(12,2) NOT NULL,
    order_freight_value NUMERIC(12,2) NOT NULL,
    order_payment_value NUMERIC(12,2),
    payment_count SMALLINT NOT NULL,
    days_purchase_to_approval NUMERIC(7,2),
    days_approval_to_carrier NUMERIC(7,2),
    days_carrier_to_customer NUMERIC(7,2),
    days_purchase_to_delivery NUMERIC(7,2),
    days_promised NUMERIC(7,2) NOT NULL,
    delivery_delay_days INTEGER,
    is_delivered SMALLINT NOT NULL,
    is_late SMALLINT,
    customer_order_number SMALLINT NOT NULL,
    is_repeat_purchase SMALLINT NOT NULL,
    review_count SMALLINT NOT NULL,
    avg_review_score NUMERIC(3,2),
    CONSTRAINT pk_fact_orders PRIMARY KEY (order_id),
    CONSTRAINT fk_fact_orders_customer_key FOREIGN KEY (customer_key) REFERENCES project_dw.dim_customer (customer_key),
    CONSTRAINT fk_fact_orders_order_status_key FOREIGN KEY (order_status_key) REFERENCES project_dw.dim_order_status (order_status_key),
    CONSTRAINT fk_fact_orders_order_purchase_date_key FOREIGN KEY (order_purchase_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_orders_approved_date_key FOREIGN KEY (approved_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_orders_carrier_date_key FOREIGN KEY (carrier_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_orders_delivered_date_key FOREIGN KEY (delivered_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_orders_estimated_delivery_date_key FOREIGN KEY (estimated_delivery_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT ck_fact_orders_1 CHECK (item_count >= 0),
    CONSTRAINT ck_fact_orders_2 CHECK (order_item_value >= 0),
    CONSTRAINT ck_fact_orders_3 CHECK (order_freight_value >= 0),
    CONSTRAINT ck_fact_orders_4 CHECK (order_payment_value >= 0),
    CONSTRAINT ck_fact_orders_5 CHECK (payment_count >= 0),
    CONSTRAINT ck_fact_orders_6 CHECK (review_count >= 0),
    CONSTRAINT ck_fact_orders_7 CHECK (purchase_hour BETWEEN 0 AND 23),
    CONSTRAINT ck_fact_orders_8 CHECK (is_delivered IN (0, 1)),
    CONSTRAINT ck_fact_orders_9 CHECK (is_late IN (0, 1)),
    CONSTRAINT ck_fact_orders_10 CHECK (is_repeat_purchase IN (0, 1)),
    CONSTRAINT ck_fact_orders_11 CHECK (customer_order_number >= 1),
    CONSTRAINT ck_fact_orders_12 CHECK (avg_review_score BETWEEN 1 AND 5),
    CONSTRAINT ck_fact_orders_13 CHECK (is_delivered = 1 OR (is_late IS NULL AND delivery_delay_days IS NULL))
);
COMMENT ON TABLE project_dw.fact_orders IS 'Accumulating snapshot fact. Grain: One row per customer order (order_id), updated as the order passes purchase, approval, carrier hand-off and delivery milestones.';
COMMENT ON COLUMN project_dw.fact_orders.order_id IS 'Order identifier (degenerate dimension).';
COMMENT ON COLUMN project_dw.fact_orders.customer_key IS 'Customer who placed the order.';
COMMENT ON COLUMN project_dw.fact_orders.order_status_key IS 'Current order status.';
COMMENT ON COLUMN project_dw.fact_orders.order_purchase_date_key IS 'Order placed (role: purchase date).';
COMMENT ON COLUMN project_dw.fact_orders.approved_date_key IS 'Payment approved (role: approval date); -1 if not yet.';
COMMENT ON COLUMN project_dw.fact_orders.carrier_date_key IS 'Handed to carrier (role: carrier date); -1 if not yet.';
COMMENT ON COLUMN project_dw.fact_orders.delivered_date_key IS 'Delivered to customer (role: delivery date); -1 if not yet.';
COMMENT ON COLUMN project_dw.fact_orders.estimated_delivery_date_key IS 'Delivery date promised at purchase (role: estimated date).';
COMMENT ON COLUMN project_dw.fact_orders.purchase_hour IS 'Hour of day the order was placed (0-23).';
COMMENT ON COLUMN project_dw.fact_orders.item_count IS 'Number of item rows in the order (0 for orders without items).';
COMMENT ON COLUMN project_dw.fact_orders.order_item_value IS 'Sum of item_price for the order.';
COMMENT ON COLUMN project_dw.fact_orders.order_freight_value IS 'Sum of freight_value for the order.';
COMMENT ON COLUMN project_dw.fact_orders.order_payment_value IS 'Total amount paid for the order (all payment records).';
COMMENT ON COLUMN project_dw.fact_orders.payment_count IS 'Number of payment records for the order.';
COMMENT ON COLUMN project_dw.fact_orders.days_purchase_to_approval IS 'Elapsed days from purchase to payment approval.';
COMMENT ON COLUMN project_dw.fact_orders.days_approval_to_carrier IS 'Elapsed days from approval to carrier hand-off (seller handling).';
COMMENT ON COLUMN project_dw.fact_orders.days_carrier_to_customer IS 'Elapsed days in transit.';
COMMENT ON COLUMN project_dw.fact_orders.days_purchase_to_delivery IS 'Total elapsed days from purchase to delivery.';
COMMENT ON COLUMN project_dw.fact_orders.days_promised IS 'Promised lead time: purchase to estimated delivery.';
COMMENT ON COLUMN project_dw.fact_orders.delivery_delay_days IS 'Delivered date minus estimated date in whole days (negative = early).';
COMMENT ON COLUMN project_dw.fact_orders.is_delivered IS '1 if status = delivered and a delivery date exists, else 0.';
COMMENT ON COLUMN project_dw.fact_orders.is_late IS '1 if delivered after the estimated date, 0 if on time; NULL when is_delivered = 0.';
COMMENT ON COLUMN project_dw.fact_orders.customer_order_number IS 'Sequence of this order among the customer''s orders (1 = first purchase).';
COMMENT ON COLUMN project_dw.fact_orders.is_repeat_purchase IS '1 if customer_order_number > 1.';
COMMENT ON COLUMN project_dw.fact_orders.review_count IS 'Number of reviews received for the order.';
COMMENT ON COLUMN project_dw.fact_orders.avg_review_score IS 'Mean review score of the order (1-5); NULL if no review.';

-- Transaction fact. Grain: One row per payment record of an order (order_id + payment_sequential). An order paid with a card and two vouchers has three rows.
CREATE TABLE project_dw.fact_payments (
    order_id VARCHAR(32) NOT NULL,
    payment_sequential SMALLINT NOT NULL,
    order_purchase_date_key INTEGER NOT NULL,
    customer_key INTEGER NOT NULL,
    payment_type_key SMALLINT NOT NULL,
    order_status_key SMALLINT NOT NULL,
    payment_value NUMERIC(10,2) NOT NULL,
    payment_installments SMALLINT NOT NULL,
    CONSTRAINT pk_fact_payments PRIMARY KEY (order_id, payment_sequential),
    CONSTRAINT fk_fact_payments_order_purchase_date_key FOREIGN KEY (order_purchase_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_payments_customer_key FOREIGN KEY (customer_key) REFERENCES project_dw.dim_customer (customer_key),
    CONSTRAINT fk_fact_payments_payment_type_key FOREIGN KEY (payment_type_key) REFERENCES project_dw.dim_payment_type (payment_type_key),
    CONSTRAINT fk_fact_payments_order_status_key FOREIGN KEY (order_status_key) REFERENCES project_dw.dim_order_status (order_status_key),
    CONSTRAINT ck_fact_payments_1 CHECK (payment_sequential >= 1),
    CONSTRAINT ck_fact_payments_2 CHECK (payment_value >= 0),
    CONSTRAINT ck_fact_payments_3 CHECK (payment_installments >= 1)
);
COMMENT ON TABLE project_dw.fact_payments IS 'Transaction fact. Grain: One row per payment record of an order (order_id + payment_sequential). An order paid with a card and two vouchers has three rows.';
COMMENT ON COLUMN project_dw.fact_payments.order_id IS 'Order identifier (degenerate dimension). Part of PK.';
COMMENT ON COLUMN project_dw.fact_payments.payment_sequential IS 'Sequence of the payment within the order (1..29). Part of PK.';
COMMENT ON COLUMN project_dw.fact_payments.order_purchase_date_key IS 'Date the order was placed (no separate payment date exists in source).';
COMMENT ON COLUMN project_dw.fact_payments.customer_key IS 'Customer who paid.';
COMMENT ON COLUMN project_dw.fact_payments.payment_type_key IS 'Payment method.';
COMMENT ON COLUMN project_dw.fact_payments.order_status_key IS 'Current status of the parent order.';
COMMENT ON COLUMN project_dw.fact_payments.payment_value IS 'Amount paid in this payment record (BRL). Not the same as item sales revenue.';
COMMENT ON COLUMN project_dw.fact_payments.payment_installments IS 'Number of instalments chosen (0 in 2 source rows, treated as 1).';

-- Transaction fact. Grain: One row per review submitted for an order (review_id + order_id). The same review_id can cover more than one order, and an order can receive more than one review.
CREATE TABLE project_dw.fact_reviews (
    review_id VARCHAR(32) NOT NULL,
    order_id VARCHAR(32) NOT NULL,
    customer_key INTEGER NOT NULL,
    review_creation_date_key INTEGER NOT NULL,
    review_answer_date_key INTEGER NOT NULL,
    review_score SMALLINT NOT NULL,
    response_hours NUMERIC(8,2) NOT NULL,
    has_comment_title SMALLINT NOT NULL,
    has_comment_message SMALLINT NOT NULL,
    CONSTRAINT pk_fact_reviews PRIMARY KEY (review_id, order_id),
    CONSTRAINT fk_fact_reviews_customer_key FOREIGN KEY (customer_key) REFERENCES project_dw.dim_customer (customer_key),
    CONSTRAINT fk_fact_reviews_review_creation_date_key FOREIGN KEY (review_creation_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT fk_fact_reviews_review_answer_date_key FOREIGN KEY (review_answer_date_key) REFERENCES project_dw.dim_date (date_key),
    CONSTRAINT ck_fact_reviews_1 CHECK (review_score BETWEEN 1 AND 5),
    CONSTRAINT ck_fact_reviews_2 CHECK (response_hours >= 0),
    CONSTRAINT ck_fact_reviews_3 CHECK (has_comment_title IN (0, 1)),
    CONSTRAINT ck_fact_reviews_4 CHECK (has_comment_message IN (0, 1))
);
COMMENT ON TABLE project_dw.fact_reviews IS 'Transaction fact. Grain: One row per review submitted for an order (review_id + order_id). The same review_id can cover more than one order, and an order can receive more than one review.';
COMMENT ON COLUMN project_dw.fact_reviews.review_id IS 'Review identifier (degenerate). Part of PK.';
COMMENT ON COLUMN project_dw.fact_reviews.order_id IS 'Reviewed order (degenerate). Part of PK.';
COMMENT ON COLUMN project_dw.fact_reviews.customer_key IS 'Customer who wrote the review.';
COMMENT ON COLUMN project_dw.fact_reviews.review_creation_date_key IS 'Date the satisfaction survey was sent (role: review date).';
COMMENT ON COLUMN project_dw.fact_reviews.review_answer_date_key IS 'Date the customer answered (role: answer date).';
COMMENT ON COLUMN project_dw.fact_reviews.review_score IS 'Satisfaction score 1 (worst) to 5 (best).';
COMMENT ON COLUMN project_dw.fact_reviews.response_hours IS 'Hours between survey creation and customer answer.';
COMMENT ON COLUMN project_dw.fact_reviews.has_comment_title IS '1 if the customer wrote a comment title.';
COMMENT ON COLUMN project_dw.fact_reviews.has_comment_message IS '1 if the customer wrote a comment message.';
